def process(exceedanceByYear) -> pd.DataFrame:
    import pandas as pd
    years = sorted(exceedanceByYear['year'].astype(int).tolist())
    # Store as string to avoid LIST attribute type issues in the runtime
    return pd.DataFrame({'years': [str(years)]})
